#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SceneGraph {
    pub nodes: Vec<SceneNode>,
}

pub fn leaf_paths(graph: &SceneGraph, root: usize) -> Vec<Vec<usize>> {
    fn walk(
        graph: &SceneGraph,
        node: usize,
        current: &mut Vec<usize>,
        output: &mut Vec<Vec<usize>>,
        visited: &mut [bool],
    ) {
        if visited[node] {
            return;
        }
        visited[node] = true;
        current.push(node);

        if graph.nodes[node].children.is_empty() {
            output.push(current.clone());
        } else {
            for &child in &graph.nodes[node].children {
                walk(graph, child, current, output, visited);
            }
        }

        current.pop();
    }

    let mut output = Vec::new();
    let mut current = Vec::new();
    let mut visited = vec![false; graph.nodes.len()];
    walk(graph, root, &mut current, &mut output, &mut visited);
    output
}
","known_bad_label":"A global visited set suppresses shared nodes, so valid root-to-leaf paths through later parent aliases are omitted."},{"id":"cap-v2-graph_and_tree-rust-repair-01","problem":"Repair the parent-chain traversal below. Return one complete `solution.rs` source file and do not define `main`.

Preserve the public API declared in the source. `parents[node]` is either the node's parent or `None` for a root. `trace_to_root` must return the path from `start` through its ancestors to the root, including both endpoints. It must return `TraceError::StartOutOfRange` when `start` is not a node, `TraceError::ParentOutOfRange` when a visited node names an invalid parent, and `TraceError::Cycle` when traversal revisits a node. For a cycle, `node` must be the first node that would be visited for a second time. Malformed input must return an error rather than panic.

Use only the Rust standard library; do not access the filesystem, network, clock, or randomness.

Known-bad source to repair:

```rust
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TraceError {
    StartOutOfRange { start: usize },
    ParentOutOfRange { node: usize, parent: usize },
    Cycle { node: usize },
}

pub fn trace_to_root(
    parents: &[Option<usize>],
    start: usize,
) -> Result<Vec<usize>, TraceError> {
    if start >= parents.len() {
        return Err(TraceError::StartOutOfRange { start });
    }

    let mut path = Vec::new();
    let mut seen = vec![false; parents.len()];
    let mut current = start;

    loop {
        if seen[current] {
            return Err(TraceError::Cycle { node: current });
        }
        seen[current] = true;
        path.push(current);

        match parents[current] {
            None => return Ok(path),
            Some(parent) => current = parent,
        }
    }
}
