mod solution;

use solution::{run_events, Event, Listener};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

static TEST_LOCK: Mutex<()> = Mutex::new(());
static CALL_LOG: Mutex<Vec<(u8, u64, i32)>> = Mutex::new(Vec::new());
static PHASE: AtomicUsize = AtomicUsize::new(0);
static COMPLETION_CALLS: AtomicUsize = AtomicUsize::new(0);

fn listener_a(event: &Event) -> Vec<Event> {
    assert_eq!(PHASE.load(Ordering::SeqCst), 0, "listener called after completion");
    CALL_LOG.lock().unwrap().push((1, event.id, event.payload));
    match event.id {
        1 => vec![
            Event { id: 2, payload: 20 },
            Event { id: 1, payload: -1 },
        ],
        2 => vec![Event { id: 4, payload: 40 }],
        _ => Vec::new(),
    }
}

fn listener_b(event: &Event) -> Vec<Event> {
    assert_eq!(PHASE.load(Ordering::SeqCst), 0, "listener called after completion");
    CALL_LOG.lock().unwrap().push((2, event.id, event.payload));
    match event.id {
        1 => vec![Event { id: 3, payload: 30 }],
        2 => vec![
            Event { id: 3, payload: 300 },
            Event { id: 5, payload: 50 },
        ],
        _ => Vec::new(),
    }
}

fn completion(ids: &[u64]) -> String {
    assert_eq!(PHASE.swap(1, Ordering::SeqCst), 0, "completion invoked more than once");
    COMPLETION_CALLS.fetch_add(1, Ordering::SeqCst);
    ids.iter().map(u64::to_string).collect::<Vec<_>>().join(",")
}

fn reset_state() {
    CALL_LOG.lock().unwrap().clear();
    PHASE.store(0, Ordering::SeqCst);
    COMPLETION_CALLS.store(0, Ordering::SeqCst);
}

#[test]
fn fifo_deduplication_listener_order_and_completion_contract() {
    let _guard = TEST_LOCK.lock().unwrap();
    reset_state();

    let initial = vec![
        Event { id: 1, payload: 10 },
        Event { id: 2, payload: 999 },
    ];
    let listeners: [Listener; 2] = [listener_a, listener_b];
    let report = run_events(initial, &listeners, completion);

    assert_eq!(report.handled_ids, vec![1, 2, 3, 4, 5]);
    assert_eq!(report.completion_value, "1,2,3,4,5");
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
    assert_eq!(PHASE.load(Ordering::SeqCst), 1);
    assert_eq!(
        *CALL_LOG.lock().unwrap(),
        vec![
            (1, 1, 10), (2, 1, 10),
            (1, 2, 999), (2, 2, 999),
            (1, 3, 30), (2, 3, 30),
            (1, 4, 40), (2, 4, 40),
            (1, 5, 50), (2, 5, 50),
        ]
    );
}

#[test]
fn empty_input_still_completes_once() {
    let _guard = TEST_LOCK.lock().unwrap();
    reset_state();

    let listeners: [Listener; 2] = [listener_a, listener_b];
    let report = run_events(Vec::new(), &listeners, completion);

    assert!(report.handled_ids.is_empty());
    assert_eq!(report.completion_value, "");
    assert!(CALL_LOG.lock().unwrap().is_empty());
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
}

#[test]
fn no_listeners_handles_boundary_values_and_discards_duplicate_ids() {
    let _guard = TEST_LOCK.lock().unwrap();
    reset_state();

    let report = run_events(
        vec![
            Event { id: 0, payload: i32::MIN },
            Event { id: u64::MAX, payload: i32::MAX },
            Event { id: u64::MAX, payload: 0 },
        ],
        &[],
        completion,
    );

    assert_eq!(report.handled_ids, vec![0, u64::MAX]);
    assert_eq!(report.completion_value, format!("0,{}", u64::MAX));
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
}
