mod solution;

use solution::{Event, EventBus};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

static TEST_LOCK: Mutex<()> = Mutex::new(());
static PHASE: AtomicUsize = AtomicUsize::new(0);
static COMPLETION_CALLS: AtomicUsize = AtomicUsize::new(0);

fn old_alpha(_: &Event) -> String {
    panic!("replaced handler was invoked")
}

fn new_alpha(event: &Event) -> String {
    assert_eq!(PHASE.load(Ordering::SeqCst), 0, "handler called after completion");
    format!("new-alpha:{}:{}", event.topic, event.value)
}

fn beta(event: &Event) -> String {
    assert_eq!(PHASE.load(Ordering::SeqCst), 0, "handler called after completion");
    format!("beta:{}", event.value)
}

fn gamma(event: &Event) -> String {
    assert_eq!(PHASE.load(Ordering::SeqCst), 0, "handler called after completion");
    format!("gamma:{}", event.topic)
}

fn completion(results: &[String]) -> usize {
    assert_eq!(PHASE.swap(1, Ordering::SeqCst), 0, "completion invoked more than once");
    COMPLETION_CALLS.fetch_add(1, Ordering::SeqCst);
    results.iter().map(String::len).sum()
}

fn reset_state() {
    PHASE.store(0, Ordering::SeqCst);
    COMPLETION_CALLS.store(0, Ordering::SeqCst);
}

#[test]
fn replacement_preserves_position_and_new_keys_append() {
    let _guard = TEST_LOCK.lock().unwrap();
    reset_state();

    let mut bus = EventBus::new();
    bus.subscribe("alpha".to_string(), old_alpha);
    bus.subscribe("beta".to_string(), beta);
    bus.subscribe("alpha".to_string(), new_alpha);
    bus.subscribe("gamma".to_string(), gamma);

    let event = Event { topic: "orders".to_string(), value: 17 };
    let original = event.clone();
    let report = bus.dispatch(&event, completion);
    let expected = vec![
        "new-alpha:orders:17".to_string(),
        "beta:17".to_string(),
        "gamma:orders".to_string(),
    ];

    assert_eq!(report.handler_results, expected);
    assert_eq!(
        report.completion_value,
        report.handler_results.iter().map(String::len).sum::<usize>()
    );
    assert_eq!(event, original, "dispatch mutated its borrowed event");
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
}

#[test]
fn dispatch_is_stable_across_repeated_calls() {
    let _guard = TEST_LOCK.lock().unwrap();
    let mut bus = EventBus::new();
    bus.subscribe("alpha".to_string(), new_alpha);
    bus.subscribe("beta".to_string(), beta);
    let event = Event { topic: "stable".to_string(), value: -4 };

    reset_state();
    let first = bus.dispatch(&event, completion);
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);

    reset_state();
    let second = bus.dispatch(&event, completion);
    assert_eq!(first, second);
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
}

#[test]
fn empty_registry_completes_once_with_empty_results() {
    let _guard = TEST_LOCK.lock().unwrap();
    reset_state();

    let bus = EventBus::new();
    let event = Event { topic: String::new(), value: i32::MIN };
    let report = bus.dispatch(&event, completion);

    assert!(report.handler_results.is_empty());
    assert_eq!(report.completion_value, 0);
    assert_eq!(COMPLETION_CALLS.load(Ordering::SeqCst), 1);
}
