#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TraceError {
    StartOutOfRange { start: usize },
    ParentOutOfRange { node: usize, parent: usize },
    Cycle { node: usize },
}

pub fn trace_to_root(
    parents: &[Option<usize>],
    start: usize,
) -> Result<Vec<usize>, TraceError> {
    if start >= parents.len() {
        return Err(TraceError::StartOutOfRange { start });
    }

    let mut path = Vec::new();
    let mut seen = vec![false; parents.len()];
    let mut current = start;

    loop {
        if seen[current] {
            return Err(TraceError::Cycle { node: current });
        }
        seen[current] = true;
        path.push(current);

        match parents[current] {
            None => return Ok(path),
            Some(parent) => current = parent,
