{"items":[{"id":"cap-v2-graph_and_tree-rust-repair-02","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{branch_totals, HierarchyError};

#[test]
fn empty_hierarchy_has_no_totals() {
    assert_eq!(branch_totals(&[]), Ok(Vec::new()));
}

#[test]
fn computes_nested_branch_totals_in_input_order() {
    let rows = vec![
        (0, 5),
        (1, 2),
        (2, 3),
        (2, 4),
        (1, 7),
        (2, -2),
    ];
    let original = rows.clone();

    assert_eq!(branch_totals(&rows), Ok(vec![19, 9, 3, 4, 5, -2]));
    assert_eq!(rows, original);
}

#[test]
fn supports_single_row_and_one_level_descent() {
    assert_eq!(branch_totals(&[(0, 42)]), Ok(vec![42]));
    assert_eq!(
        branch_totals(&[(0, 1), (1, 2), (1, 3)]),
        Ok(vec![6, 2, 3])
    );
}

#[test]
fn rejects_nonzero_root_depth() {
    assert_eq!(
        branch_totals(&[(1, 10), (2, 20)]),
        Err(HierarchyError::RootDepth)
    );
    assert_eq!(
        branch_totals(&[(usize::MAX, 10)]),
        Err(HierarchyError::RootDepth)
    );
}

#[test]
fn rejects_a_two_level_descent_immediately_after_root() {
    assert_eq!(
        branch_totals(&[(0, 1), (2, 2)]),
        Err(HierarchyError::SkippedLevel)
    );
}

#[test]
fn rejects_a_skipped_level_later_in_the_encoding() {
    assert_eq!(
        branch_totals(&[(0, 1), (1, 2), (2, 3), (4, 4)]),
        Err(HierarchyError::SkippedLevel)
    );
}

#[test]
fn handles_signed_value_boundaries_without_overflowing_the_result() {
    assert_eq!(
        branch_totals(&[(0, i64::MAX), (1, -1)]),
        Ok(vec![i64::MAX - 1, -1])
    );
    assert_eq!(
        branch_totals(&[(0, i64::MIN), (1, 1)]),
        Ok(vec![i64::MIN + 1, 1])
    );
}"},{"id":"cap-v2-numeric_reasoning-rust-generation-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::apportion;

#[test]
fn rejects_empty_and_all_zero_weights() {
    assert_eq!(apportion(&[], 10), None);
    assert_eq!(apportion(&[0, 0, 0], 10), None);
}

#[test]
fn apportions_by_largest_fractional_remainder() {
    assert_eq!(apportion(&[5, 3, 2], 7), Some(vec![4, 2, 1]));
}

#[test]
fn equal_remainders_prefer_earlier_positions() {
    assert_eq!(apportion(&[1, 1, 1, 1], 2), Some(vec![1, 1, 0, 0]));
    assert_eq!(apportion(&[1, 1, 1], 5), Some(vec![2, 2, 1]));
}

