    }

    pub fn find(&mut self, low: u32, high: u32) -> Vec<u32> {
        for first in 1u32..=9 {
            let mut last = first;
            let mut value = first;

            while last + 2 <= 9 {
                last += 2;
                value = value * 10 + last;
                if value >= low && value <= high {
